function duaJumlah(arr, target) {
  const lihat = new Map();
  for (let j = 0; j < arr.length; j++) {
    const butuh = target - arr[j];
    if (lihat.has(butuh)) return [lihat.get(butuh), j];
    if (!lihat.has(arr[j])) lihat.set(arr[j], j);
  }
  return [];
}

