func duaJumlah(arr []int, target int) []int {
	lihat := map[int]int{}
	for j, x := range arr {
		if i, ada := lihat[target-x]; ada {
			return []int{i, j}
		}
		if _, ada := lihat[x]; !ada {
			lihat[x] = j
		}
	}
	return []int{}
}
